// The CLI's generated files and `pnpm api-schema:generate`: the script renders them with api-schema's
// own files and the gatekeeper app UIs', so every generation writes them, and the ones on disk (which
// the `test` task and `test:run` generate first) are what it renders. Scratch files go under the OS
// temp directory.

import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { pathToFileURL } from "node:url";
import { findGatekeeperApps, GATEKEEPER_APPS_DIR, renderApiSchema } from "../../api-schema/scripts/generate.ts";
import { renderAgentTypes, type Schema } from "./emit.ts";

const ROOT = join(import.meta.dirname, "..", "..", "..");
const CLI_FILES = ["packages/api-cli/generated/commands.ts", "packages/api-cli/generated/agent-types.ts"];

/** A generated schema, by its path from the repository root. */
const read = (path: string) => JSON.parse(readFileSync(join(ROOT, path), "utf8")) as Schema;

test("pnpm api-schema:generate renders the CLI's files, and the files on disk are what it renders", () => {
  // generateApiSchema writes exactly these files, and --if-stale regenerates when one differs from
  // what it wrote: that is what keeps the CLI's in step with api.ts.
  const schema = read("packages/api-schema/generated/workshop-api.schema.json");
  const apps = findGatekeeperApps().map((app) => ({ ...app, schema: read(`${GATEKEEPER_APPS_DIR}/${app.vendor}.schema.json`) }));
  const files = renderApiSchema(schema, apps);
  const paths = files.map((file) => file.path);
  for (const path of ["packages/api-schema/generated/workshop-api.schema.json", ...CLI_FILES]) {
    assert.ok(paths.includes(path), path);
  }
  for (const path of CLI_FILES) {
    assert.equal(files.find((file) => file.path === path)!.contents, readFileSync(join(ROOT, path), "utf8"), path);
  }
});

test("agent-types.ts holds the agent declarations, whole, per service and per gatekeeper app UI, each text line for line", async (t) => {
  const agent = {
    declarations: "/** `a` and ${b} */\nexport interface A {\n  \"x\"(): void;\n}\n", fragments: { A: "a\n", "not-a-name": "" },
    apps: { sketch: "export interface SketchApi {}\n" },
  };
  const dir = mkdtempSync(join(tmpdir(), "api-cli-generate-"));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const path = join(dir, "agent-types.ts");
  writeFileSync(path, renderAgentTypes(agent));
  const text = readFileSync(path, "utf8");
  assert.match(text, /^\/\/ Generated by `pnpm api-schema:generate` \(packages\/api-cli\/generator\/emit\.ts\): .*; do not edit\.\n/);
  assert.match(text, /^ {2}"export interface A \{",$/m);
  const module = await import(pathToFileURL(path).href) as { declarations: string; fragments: Record<string, string>; apps: Record<string, string> };
  assert.deepEqual({ declarations: module.declarations, fragments: module.fragments, apps: module.apps }, agent);
});

test("the gatekeeper app UIs are the gatekeepers with a src/app-api.ts, by vendor id", () => {
  const apps = findGatekeeperApps();
  assert.deepEqual(apps.map(({ vendor, file, source }) => ({ vendor, file, entryName: source.entryName })), [
    { vendor: "context", file: "packages/gatekeeper-context/src/app-api.ts", entryName: "AppApi" },
    { vendor: "scheduler", file: "packages/gatekeeper-scheduler/src/app-api.ts", entryName: "AppApi" },
  ]);
  for (const { vendor, source } of apps) assert.equal(source.tsconfig, join(ROOT, "packages", `gatekeeper-${vendor}`, "tsconfig.json"));
});

test("only a gatekeeper package's src/app-api.ts counts, and its directory gives its vendor id", (t) => {
  const root = mkdtempSync(join(tmpdir(), "api-cli-apps-"));
  t.after(() => rmSync(root, { recursive: true, force: true }));
  const pkg = (dir: string, appApi: boolean) => {
    mkdirSync(join(root, "packages", dir, "src"), { recursive: true });
    if (appApi) writeFileSync(join(root, "packages", dir, "src", "app-api.ts"), "export type { X as AppApi } from \"./x.js\";\n");
  };
  pkg("gatekeeper-mcp-portal", true);
  pkg("gatekeeper-none", false);
  pkg("workshop-other", true);
  assert.deepEqual(findGatekeeperApps(root).map(({ vendor, file }) => ({ vendor, file })),
    [{ vendor: "mcp_portal", file: "packages/gatekeeper-mcp-portal/src/app-api.ts" }]);
});
